-- Tanda 7: Los Rezagados (9 registros).
-- Seed idempotente para Preview. Los registros permanecen inactivos hasta la aprobación funcional.
begin;
on conflict (plato_id) do update set sinonimos=excluded.sinonimos, resumen=excluded.resumen, hack=excluded.hack, que_observar=excluded.que_observar, activo=false, updated_at=now();
commit;
